-- anwendungsbereich
update public.fields set verification_status='verified_against_standard', verification_quote='Dieses Merkblatt gilt für die Wiederverwendung aufbereiteten Wassers aus kommunalen Kläranlagen mit überwiegendem Anteil häuslichen Schmutzwassers für landwirtschaftliche, gartenbauliche und urbane Anwendungen. Hierzu gehören neben der Bewässerung landwirtschaftlicher Flächen und gartenbaulicher Kulturen auch die Bewässerung von zum Beispiel Parks, Straßenbegleitgrün, Grün- und Sportanlagen oder die Straßenreinigung. | Die Wiederverwendung von aufbereitetem Wasser aus kommunalen Kläranlagen als Brauchwasser für industrielle Anwendungen wird in diesem Merkblatt nicht betrachtet, da je nach Branche und Anwendungszweck unterschiedliche Ansprüche hinsichtlich der Wasserqualität zu erfüllen sind. — printed p.10', verification_note='md-verified 2026-09-05 (§1 Anwendungsbereich, printed p.10 derived) [VC] — enum value industrie_ausgeschlossen is the printed exclusion offered as a selectable option (STAGED S-8 note)', verified_at=now() where id='07c1546d-ebd7-4421-a1f9-8e30c1e227ba' and verification_status not in ('verified_against_standard','corrected');
-- haeusliches_sw_anteil_ueberwiegend
