update public.fields set verification_status='verified_against_standard', verification_quote='In Tabelle 2 sind auszugsweise die unter anderem um Vorgaben aus DIN 19650:1999 ergänzten Wassergüteklassen der EU-WasserWVVO für unterschiedliche Nutzungskategorien aufgeführt. Die vier Güteklassen werden entsprechend der Anwendungszwecke differenziert. Für die mittleren Güteklassen B-1 und C-1 erfolgt zudem eine Abstufung gemäß der angewendeten Bewässerungsmethode. [...] Die weitere Aufteilung in die Güteklassen B-1 und B-2 bzw. C-1 und C -2 dient der Differenzierung der Anforderungen an die Validierung der Leistungsziele zur Reduktion von Pathogenen (siehe 3.3) zwischen den Anwendungen im Landschaftsbau und in der Freiflächenpflege (urbane Anwendungen) gegenüber Landwirtschaft und Gartenbau. | Tabelle 2: Auszug aus Merkblatt DWA-M 1200-1:2025 Tabelle 7, mit den Anwendungsbereichen der Wasserwiederverwendung in Deutschland in Bezug zu den Güteklassen nach EU-WasserWVVO | Wassergüteklasse & Anwendungsbereich & Bewässerungsmethode, auszugsweise — printed p.14–15', verification_note='md-verified 2026-09-05 (§3.1 + Tab. 2 rows A / B-1 / B-2 / C-1 / C-2 / D, printed p.14–15 derived) [VC] — all six enum values are printed Tab. 2 rows', verified_at=now() where id='fd771138-32ea-419b-b562-684b24b9a84c' and verification_status not in ('verified_against_standard','corrected');
