-- confidence_alpha
update public.fields set verification_status='verified_against_standard', verification_quote='Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) ist eine Probenanzahl $N$ von mindestens 10 je Zu- und Ablauf vorzusehen. Für die Berechnung von Vertrauensintervallen ist die Angabe eines Konfidenzniveaus $\alpha$ erforderlich. Für $10 \leqslant N<16$ wird ein Konfidenzniveau von $\alpha=0,1$ als ausreichend betrachtet. Bei $N \geqslant 16$ kann analog zu Anhang C. 2 auf den Schätzwert für $\alpha=0,5$ zurückgegriffen werden. — printed p.76', verification_note='md-verified 2026-09-05 (Anhang C.3, printed p.76 derived) [VC] — standard_fixed pair (0,1 / 0,5) keyed on N; hand-enterable (STAGED S-10)', verified_at=now() where id='2ae37094-fbbd-45a8-b1d2-c169da6bcbda' and verification_status not in ('verified_against_standard','corrected');
