update public.fields set verification_status='verified_against_standard', verification_quote='Validierungsmonitoring durchführen | Anzahl & Zulauf & Ablauf | $\mathbf{1}$ & $\mathrm{x}_{1}=\mathbf{8 , 4} \cdot \mathbf{1 0} 0^{5}$ & $\mathrm{y}_{1}=0,3$ | $\mathbf{2}$ & $\mathrm{x}_{2}=\mathbf{1 , 6 \cdot 1 0} \mathbf{1 0}^{6}$ & $\mathrm{y}_{2}=0,5$ | N & $\mathrm{x}_{\mathrm{N}}$ & $\mathrm{y}_{\mathrm{N}}$ | Konzentrationen je 100 mL N = 16 | $\operatorname{LRV}_{\mathrm{i}}=\log _{10}\left(\mathrm{x}_{\mathrm{i}} / \mathrm{y}_{\mathrm{i}}\right)$ | Im Zulauf genügen den standardisierten Analysemethoden entsprechende (kleinere) Probenvolumen. — printed p.75 / p.77', verification_note='md-verified 2026-09-05 (Anhang C.2 Bild C.1 Wertetabelle + C.4, printed p.75 / p.77 derived) [VC] — table values are the printed worked example ("Beispielhafte Werte sind kursiv gedruckt")', verified_at=now() where id='99daef14-0b1c-41d1-85a8-cd978f5e3a9d' and verification_status not in ('verified_against_standard','corrected');
-- log10_reduktion
update public.fields set verification_status='verified_against_standard', verification_quote='Die $\log _{10}$-Reduktion wird jeweils aus der Zulaufkonzentration $C_{\text {zulauf }}$ und Ablaufkonzentration $C_{\text {Ablauf }}$ der Indikatororganismen berechnet: | $\log _{10} \text {-Reduktion }=\log _{10}\left(C_{\text {Zulauf }} / C_{\text {Ablauf }}\right) \tag{1}$ | Hierbei müssen mindestens $90 \%$ der Proben die Leistungsziele erreichen (Klasse A). Das Vorgehen wird im Einzelnen in 3.3.3 dargelegt. — printed p.19', verification_note='md-verified 2026-09-05 (§3.3.2 Gl. (1), printed p.19 derived) [VC] — derived output of Gl. 1 yet is_required=true and hand-enterable (STAGED S-8 / S-10, #22 class)', verified_at=now() where id='ab3ac65b-602a-479a-889f-745f2f6f214c' and verification_status not in ('verified_against_standard','corrected');
-- probenanzahl_zulauf
update public.fields set verification_status='verified_against_standard', verification_quote='Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. | Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) ist eine Probenanzahl N von 16 je Zu- und Ablauf vorzusehen (in Anlehnung an die EU-Badegewässerrichtlinie, Richtlinie 2006/7/EG). | Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) ist eine Probenanzahl $N$ von mindestens 10 je Zu- und Ablauf vorzusehen. — printed p.21 / p.75 / p.76', verification_note='md-verified 2026-09-05 (§3.3.3 vereinfacht + Anhang C.2 + C.3, printed p.21 / p.75 / p.76 derived) [VC] — three printed minima keyed on the monitoring variant (16 / 16 / 10); gate REQ-05 only encodes the first (STAGED S-4)', verified_at=now() where id='253e733d-ca69-4cfe-ab5e-a372a52a4fda' and verification_status not in ('verified_against_standard','corrected');
-- validierungsmonitoring_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Validierung der Aufbereitungseinrichtung können zwei Varianten des Validierungsmonitorings unterschieden werden: 1. das vereinfachte Validierungsmonitoring, wenn die neue Anlage hinsichtlich ihrer verfahrenstechnischen Auslegung einer Referenzanlage entspricht [...] 2. das umfängliche Validierungsmonitoring, wenn die Genehmigungsbehörde dieses bei Anwendung der Alternativvariante in der Planungsphase vorgibt. Das Vorgehen ist in Anhang C beschrieben. | Für die Ermittlung der Verteilung der $\log _{10}$-Reduktionen können zwei verschiedene Ansätze angewendet werden: 1. die analytische Berechnung des geforderten Perzentils über gepaarte Auswertung der $\log _{10}$-Reduktionswerte (Basisvariante) sowie 2. das Monte-Carlo-Verfahren zur Berechnung des geforderten Perzentils und die ungepaarte Auswertung (Alternativvariante, vorteilhaft bei ungleicher Probenanzahl im Zu- und Ablauf) — printed p.21–22 / p.74', verification_note='md-verified 2026-09-05 (§3.3.3 Inbetriebnahmephase + Anhang C.1, printed p.21–22 / p.74 derived) [VC] — enum has a bare "umfaenglich" AND the two printed sub-variants umfaenglich_basis / umfaenglich_montecarlo (overlap, STAGED S-6)', verified_at=now() where id='9e838a05-17fd-461e-8e8f-76a6c4c9f519' and verification_status not in ('verified_against_standard','corrected');
-- c_zulauf
update public.fields set verification_status='verified_against_standard', verification_quote='Dazu ist gemäß EU-Leitlinie 2022/C 298/01 durch eine analytische Kontrolle in einem Validierungsprotokoll zu dokumentieren, dass mit den gewählten Aufbereitungsschritten die erforderliche Reduktionsleistung (Leistungsziel) als $\log _{10}$-Reduktion vom Zulauf der kommunalen Abwasserbehandlungsanlage (Rohabwasser) bis zum Punkt der Einhaltung nach der weitergehenden Aufbereitung (aufbereitetes Wasser) eingehalten wird. Die $\log _{10}$-Reduktion wird jeweils aus der Zulaufkonzentration $C_{\text {zulauf }}$ und Ablaufkonzentration $C_{\text {Ablauf }}$ der Indikatororganismen berechnet: | $C_{\text {Zulauf }}$ & Zulaufkonzentration — printed p.19 / p.12', verification_note='md-verified 2026-09-05 (§3.3.2 + Tab. 1 Formelzeichen, printed p.19 / p.12 derived) [VC] — input of Gl. 1; Zulauf = Rohabwasser (Kläranlagenzulauf) per §3.3.2', verified_at=now() where id='50801cba-9cb2-48ec-bb0e-2175c2468c99' and verification_status not in ('verified_against_standard','corrected');
-- c_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Die $\log _{10}$-Reduktion wird jeweils aus der Zulaufkonzentration $C_{\text {zulauf }}$ und Ablaufkonzentration $C_{\text {Ablauf }}$ der Indikatororganismen berechnet: | $C_{\text {Ablauf }}$ & Ablaufkonzentration | Für den Fall, dass die Konzentration im Ablauf $C_{\text {Ablauf }}$ unterhalb der Nachweisgrenze ist, ist die $\log _{10}$ Reduktion mit der Nachweisgrenze zu ermitteln. — printed p.19 / p.12 / p.75', verification_note='md-verified 2026-09-05 (§3.3.2 + Tab. 1 + Anhang C.2, printed p.19 / p.12 / p.75 derived) [VC] — input of Gl. 1; Ablauf = Punkt der Einhaltung nach der weitergehenden Aufbereitung; the "<NWG → use NWG" rule is not encoded in Gl. 1 (STAGED S-10)', verified_at=now() where id='56a0f534-1407-4b66-928c-f920cf176aa1' and verification_status not in ('verified_against_standard','corrected');
-- log10_reduktionen (json)
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn sich die Aufbereitungseinrichtung innerhalb der spezifizierten Betriebsbedingungen befindet, werden aus den Zu- und Ablaufwerten paarweise die $\log _{10}$-Reduktionen berechnet: | Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. | 50. Perzentil = Median (Klassen B-1 und C-1) | Für die Validierung ist die Verteilung der $\log _{10}$-Reduktionswerte heranzuziehen. — printed p.75 / p.74', verification_note='md-verified 2026-09-05 (Anhang C.2 + C.1, printed p.75 / p.74 derived) [VC] — the array is the printed "Gesamtheit der ermittelten log10-Reduktionswerte" (N=16 paired); is_required=true although only the umfängliche Basisvariante needs it (STAGED S-8)', verified_at=now() where id='1fe418ca-640b-4754-a796-daf3f15a260f' and verification_status not in ('verified_against_standard','corrected');
-- validierungsdauer_wochen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Dauer der Validierungsuntersuchungen an der Aufbereitungseinrichtung sollte sich über mindestens zwei Wochen erstrecken. Währenddessen sollte die Aufbereitungseinrichtung im Dauerbetrieb sein und sich mit betriebsüblichen Werten innerhalb der Mindestanforderungen an die Betriebsbedingungen befinden. Für den Nachweis der Validierung ist keine gezielte Variation der -Wasserqualität im Zulauf vorgesehen. — printed p.21', verification_note='md-verified 2026-09-05 (§3.3.3 Inbetriebnahmephase, printed p.21 derived) [VC] — "sollte … mindestens zwei Wochen": recommendation, not a hard limit; no gate exists (STAGED S-5 proposes warn)', verified_at=now() where id='6d45fb3b-45e8-46e6-9735-d678489bd218' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-06 · Analytischer Nachweis & Probenahme ########################
-- bsb5_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Die Basis der chemisch-physikalischen Qualitätsanforderungen stellen für die Parameter $\mathrm{BSB}_{5}$ und abfiltrierbare Stoffe (AFS) die Vorgaben der Kommunalabwasserrichtlinie 91/271/EWG dar. Für die höchste Wassergüteklasse A werden diese $\mathrm{BSB}_{5}$-Anforderungen mit einem Wert von $\leqslant 10 \mathrm{mg} / \mathrm{l}$ gemäß der EU-WasserWVVO verschärft. | Die vorgegebenen Werte für $\mathrm{BSB}_{5, \mathrm{AFS}}$ und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von $100 \%$ des vorgegebenen Werts überschreiten. — printed p.48 / p.15', verification_note='md-verified 2026-09-05 (§6.2 + §3.1; Tab. 3 row A "BSB5 ≤ 10 mg/l d)", rows B/C "BSB5 gemäß Richtlinie 91/271/EWG", printed p.48 / p.15 / p.16 derived) [VC] — no gate encodes the A-class 10 mg/l limit (STAGED S-5)', verified_at=now() where id='135c5574-a010-4f20-9d12-f0a7f6253abf' and verification_status not in ('verified_against_standard','corrected');
-- truebung_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Gemäß Tabelle 3 wird für die Wassergüteklassen A bis C grundsätzlich die Anordnung einer Filtrationsstufe gefordert und durch Anforderungen an die Trübungswerte von $\leqslant 2$ NTU spezifiziert. | Filtration: Für die Wassergüteklassen A bis C ist gemäß Tabelle 3 der Einsatz einer Filtration vor der Desinfektionsstufe gefordert, für die Wassergüteklasse D ist sie optional. Für die Güteklassen A bis C werden die Filtrationsanforderungen mit Trübungswerten von $\leqslant 2$ NTU spezifiziert. | Die vorgegebenen Werte für $\mathrm{BSB}_{5, \mathrm{AFS}}$ und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. — printed p.34 / p.32 / p.15', verification_note='md-verified 2026-09-05 (§5.2 + §5.1 Erläuterung 2 + §3.1; Tab. 3 "Trübung ≤ 2 NTU f)" for A–C, printed p.34 / p.32 / p.15 derived) [VC] — gate REQ-09 enforces ≤ 2 for A–C; is_required=true although class D has no Trübung requirement (STAGED S-8)', verified_at=now() where id='ac39e979-eda5-45f0-80b9-bff8fe236af7' and verification_status not in ('verified_against_standard','corrected');
-- probenstabilitaet_h
update public.fields set verification_status='verified_against_standard', verification_quote='Die Probenahme hat nach den anerkannten Regeln der Technik zu erfolgen. Dies gilt insbesondere bei der Probenahme im Ablauf mit geringen Konzentrationen an mikrobiologischen Parametern. Für die Bestimmung mikrobiologischer Parameter sind die Proben bis zur Bearbeitung im Labor entsprechend gekühlt zu lagern und zu transportieren. Eine ausreichende Stabilität der mikrobiologischen Proben ist bis zu 72 h nach Beginn der Probenahme zu erwarten (SEIS et al. 2024). — printed p.24', verification_note='md-verified 2026-09-05 (§3.3.4 Probenahme und -transport, printed p.24 derived) [VC] — "ist … zu erwarten" is an expectation, not a printed limit; gate REQ-07 blocks on ≤ 72 (STAGED S-4)', verified_at=now() where id='43e38d07-667f-4129-9fe7-597f4371f267' and verification_status not in ('verified_against_standard','corrected');
-- nachweisgrenze_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Validierung der $\log _{10}$-Reduktion sind Verfahren mit einer unteren Bestimmungsgrenze von $<\mathrm{KBE} / 100 \mathrm{ml}$ für die Ablaufproben zu bevorzugen. | F-spezifische Coliphagen: Der Nachweis ist nach DIN EN ISO 10705-1:2002 standardisiert. Die Bestimmungsgrenze liegt hier bei $<1$ PFU/ 100 ml . | Für den Fall, dass die Konzentration im Ablauf $C_{\text {Ablauf }}$ unterhalb der Nachweisgrenze ist, ist die $\log _{10}$ Reduktion mit der Nachweisgrenze zu ermitteln. — printed p.23 / p.75', verification_note='md-verified 2026-09-05 (§3.3.4 Auswahl der Methoden + Anhang C.2, printed p.23 / p.75 derived) [VC] — md OCR drops the "1" in "< 1 KBE/100 ml" (line 713); PDF to confirm; the md uses Bestimmungsgrenze (§3.3.4) and Nachweisgrenze (Anhang C) interchangeably', verified_at=now() where id='cb83df8a-3ad0-49ef-8d6d-9df16aa1ba37' and verification_status not in ('verified_against_standard','corrected');
-- wiederfindungsrate_viradel
update public.fields set verification_status='verified_against_standard', verification_quote='Um Coliphagen in diesen großen Probenvolumen quantifizieren zu können, ist eine Aufkonzentrierung notwendig, die mithilfe 1. der VIRADEL-Methode (engl. „virus adsorption and elution“) mit elektropositiv geladenen Memb-ran- oder Kartuschenfiltern auch in herausfordernden Wassermatrices (z. B. auch Rohabwasser) (WaterRF, 2023b) [...] erzielt werden kann. | Bild C.3: Beispiel zu nachweisbaren $\log _{10}$-Reduktionen für Coliphagen in Abhängigkeit des Probenvolumens in der Ablaufprobe. Zugrunde gelegt ist eine Aufkonzentrierung nach der VIRADELMethode [...], ein Elutionsvolumen von 300 ml , eine konstant angenommene Wiederfindungsrate von $40 \%$ und eine Nachweisgrenze von 1 PFU/ 100 ml — printed p.77', verification_note='md-verified 2026-09-05 (Anhang C.4 + Bild C.3 caption, printed p.77 derived) [VC] — CAVEAT: 40 % is the ASSUMPTION of the printed example figure, not a requirement; the field is engineer_input', verified_at=now() where id='069e9f4b-6362-4bc5-b6a3-d0e8889232d7' and verification_status not in ('verified_against_standard','corrected');
-- elutionsvolumen_viradel
update public.fields set verification_status='verified_against_standard', verification_quote='Bild C.3: Beispiel zu nachweisbaren $\log _{10}$-Reduktionen für Coliphagen in Abhängigkeit des Probenvolumens in der Ablaufprobe. Zugrunde gelegt ist eine Aufkonzentrierung nach der VIRADELMethode, eine Coliphagen-Konzentration im Zulauf von 6,31 PFU/ 100 ml bis 104 PFU/ 100 ml [...], ein Elutionsvolumen von 300 ml , eine konstant angenommene Wiederfindungsrate von $40 \%$ und eine Nachweisgrenze von 1 PFU/ 100 ml | Das Vorgehen der VIRADEL-Methode ist in US-EPA-Methode 1615 Teil 1 (US EPA 2015) beschrieben. — printed p.77', verification_note='md-verified 2026-09-05 (Bild C.3 caption + Anhang C.4, printed p.77 derived) [VC] — CAVEAT: 300 ml is the ASSUMPTION of the printed example figure, not a requirement; engineer_input', verified_at=now() where id='e4ff0ac2-956e-448e-9f19-1b0e7e8ccec7' and verification_status not in ('verified_against_standard','corrected');
-- probenvolumen_coliphagen
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach Zulaufkonzentration der mikrobiellen Indikatororganismen ist das Probenvolumen so zu wählen, dass die Nachweisgrenze das Leistungsziel abbilden kann. Dabei sind größere Probenvolumen von zum Beispiel 10 l bis 200 l für Coliphagen für die Ablaufproben angezeigt, um die Nachweisgrenze entsprechend zu verbessern. In der Regel werden Probenvolumen von circa 25 l ausreichen. — printed p.77', verification_note='md-verified 2026-09-05 (Anhang C.4, printed p.77 derived) [VC] — "zum Beispiel 10 l bis 200 l" / "circa 25 l": indicative range, standard_range under SR-2 (no auto-pick)', verified_at=now() where id='f60f4fce-6497-48d3-bfaf-2a2d02243a5a' and verification_status not in ('verified_against_standard','corrected');
-- intest_enterokokken
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3：Arbeitshilfe A：Mindestanforderungen an die Qualität von aufbereitetem Wasser für die landwirtschaftliche und urbane Wasserwiederverwendung sowie Leistungsziele für Aufbereitungs－ einrichtungen in Deutschland | E．coli $\mathrm{KBE} / 100 \mathrm{ml}$ al，cl & Intestinale Enterokokken KBE／ 100 ml cl | [Klasse A] $\leq 10^{\mathrm{a})}$ & $\leq 100$ | [Klasse B-1/B-2] $\leq 100^{\mathrm{a})}$ & $\leq 100$ | [Klasse C-1/C-2] $\leq 100$ & $\leq 400$ | Tabelle 3 (Ende) | [Klasse D] $\leq 10.000^{\mathrm{a})}$ & - ${ }^{\text {al,c) }}$ — printed p.16–17', verification_note='md-verified 2026-09-05 (Tab. 3 Qualitätsanforderungen columns, printed p.16–17 derived) [VC] — class labels in [brackets] are editorial (md glyphs lost, see pack header); Enterokokken: A ≤ 100, B ≤ 100, C ≤ 400, D "-"; NO gate enforces these printed limits (STAGED S-5)', verified_at=now() where id='d1c3dcf3-5577-405b-871d-4d558aed7934' and verification_status not in ('verified_against_standard','corrected');
-- legionella
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3 (Ende) | Fallspezifische Anforderungen | Legionella spp.: < $1.000 \mathrm{KBE} / \mathrm{L}$, wenn das Risiko der Aerosolbildung besteht; intestinale Nematoden (Eier von Helminthen): $\leq 1$ Ei pro Liter für die Bewässerung von Weideflächen oder Futterpflanzen | Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — printed p.16–17 / p.15', verification_note='md-verified 2026-09-05 (Tab. 3 Fallspezifische Anforderungen + §3.1, printed p.16–17 / p.15 derived) [VC] — NO gate enforces < 1.000 KBE/L when aerosol_risk (STAGED S-5)', verified_at=now() where id='199a742b-8a14-431d-979d-d1e33d2a6839' and verification_status not in ('verified_against_standard','corrected');
-- intest_nematoden
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3 (Ende) | Fallspezifische Anforderungen | Legionella spp.: < $1.000 \mathrm{KBE} / \mathrm{L}$, wenn das Risiko der Aerosolbildung besteht; intestinale Nematoden (Eier von Helminthen): $\leq 1$ Ei pro Liter für die Bewässerung von Weideflächen oder Futterpflanzen | Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — printed p.16–17 / p.15', verification_note='md-verified 2026-09-05 (Tab. 3 Fallspezifische Anforderungen + §3.1, printed p.16–17 / p.15 derived) [VC] — NO gate enforces ≤ 1 Ei/L when weide_oder_futter (STAGED S-5)', verified_at=now() where id='e855a7cf-08fd-4993-bd8a-05d614248f26' and verification_status not in ('verified_against_standard','corrected');
-- e_coli
update public.fields set verification_status='verified_against_standard', verification_quote='E．coli $\mathrm{KBE} / 100 \mathrm{ml}$ al，cl & Intestinale Enterokokken KBE／ 100 ml cl | [Klasse A] $\leq 10^{\mathrm{a})}$ & $\leq 100$ | [Klasse B-1/B-2] $\leq 100^{\mathrm{a})}$ & $\leq 100$ | [Klasse C-1/C-2] $\leq 100$ & $\leq 400$ | [Klasse D] $\leq 10.000^{\mathrm{a})}$ & - ${ }^{\text {al,c) }}$ | Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für $E$. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — printed p.16–17 / p.15', verification_note='md-verified 2026-09-05 (Tab. 3 E. coli column + §3.1, printed p.16–17 / p.15 derived) [VC] — class labels in [brackets] editorial (md glyphs lost); A ≤ 10, B ≤ 100, C ≤ 100, D ≤ 10.000 KBE/100 ml; NO gate enforces these printed limits (STAGED S-5)', verified_at=now() where id='096a7a4c-f045-4cf8-ac21-67f4ec120708' and verification_status not in ('verified_against_standard','corrected');
-- afs_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Die Basis der chemisch-physikalischen Qualitätsanforderungen stellen für die Parameter $\mathrm{BSB}_{5}$ und abfiltrierbare Stoffe (AFS) die Vorgaben der Kommunalabwasserrichtlinie 91/271/EWG dar. | Wenn diese Anforderungen an die Trübung kontinuierlich überwacht und eingehalten werden, kann auch davon ausgegangen werden, dass die Anforderungen zu AFS mit Werten von $\leqslant 10 \mathrm{mg} / \mathrm{l}$ eingehalten werden und somit die bei geringen Feststoffkonzentrationen aufwendige AFS-Messung nicht notwendig ist (siehe Fußnote e) zu Tabelle 3). | $\mathrm{BSB}_{5}$ und AFS gemäß Richtlinie 91/271/EWG ${ }^{\text {d),e) }}$ — printed p.48 / p.32 / p.17', verification_note='md-verified 2026-09-05 (§6.2 + §5.1 Erläuterung 2 + Tab. 3 row D; Tab. 3 rows A–C "AFS ≤ 10 mg/l" (fullwidth md), printed p.48 / p.32 / p.16–17 derived) [VC] — is_required=true although §5.1 says the AFS measurement is "nicht notwendig" when Trübung is continuously monitored (STAGED S-8); no gate on the 10 mg/l limit (S-5)', verified_at=now() where id='10cd832e-ea38-48e7-b810-8bd218e56c95' and verification_status not in ('verified_against_standard','corrected');
-- coliphagen_spiking
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn eine ausreichende Verbesserung der Nachweisgrenze, insbesondere für Coliphagen, nicht umsetzbar sein sollte, kann alternativ auch auf Spiking-Versuche zur umfänglichen Validierung der weitergehenden Aufbereitungsstufen (einzeln oder als Teil-Aufbereitungsketten) ausgewichen werden. Dabei wird die Konzentration mit nicht pathogenen Indikatororganismen (z. B. MS2- und phiX174Coliphagen) aufgestockt (Spiking) (siehe Ho et al. 2024). Nicht experimentell untersuchte Aufbereitungsstufen erhalten hier $0 \log _{10}$-Reduktionen für alle Indikatororganismen [...] Die statistische Auswertung ist in diesem Fall auf das Monte-Carlo-Verfahren (Anhang C.3) festgelegt. — printed p.78', verification_note='md-verified 2026-09-05 (Anhang C.5, printed p.78 derived) [VC] — printed consequence (Spiking ⇒ Monte-Carlo C.3 mandatory) has no gate (STAGED S-5)', verified_at=now() where id='fda53b81-3a19-4b56-a70a-846c87882b3f' and verification_status not in ('verified_against_standard','corrected');
-- analytisches_labor_akkreditiert
update public.fields set verification_status='verified_against_standard', verification_quote='Um das vereinfachte bzw. das umfängliche Validierungsmonitoring verlässlich durchzuführen, sind Anforderungen an das Qualitätsmanagement unter anderem bezüglich Laborauswahl, Probenahme, Probentransport und Auswahl der analytischen Methoden zu beachten. | Laborauswahl | Für die Analytik ist ein unabhängiges, für die entsprechenden Parameter und Analysenmethoden akkreditiertes Labor zu beauftragen. — printed p.23', verification_note='md-verified 2026-09-05 (§3.3.4 Laborauswahl, printed p.23 derived) [VC] — "ist … zu beauftragen": hard; block in REQ-07 justified', verified_at=now() where id='4646b040-51b1-48d5-88eb-25722d4a501c' and verification_status not in ('verified_against_standard','corrected');
-- probennahme_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist entsprechend DIN 38402-11:2009 auf die Entnahme repräsentativer Proben zur Bestimmung der mikrobiologischen und physikalisch-chemischen Parameter zu achten. Dies erfolgt bevorzugt durch Mischproben über 24 h (Schreiber et al. 2019, DIN 38402-11:2009, EU-Kommunalabwasserrichtlinie (Richtlinie 2024/3019). Durch 24-h-Mischproben verringert sich die Streuung der ermittelten Log $_{10}$-Reduktionen aufgrund von veränderlichen Zulaufbedingungen entscheidend [...] Alternativ können qualifizierte Stichproben oder einfache Stichproben verwendet werden, die um die hydraulische Verweilzeit versetzt sind (als korrespondierende Proben von Zuund Ablauf). — printed p.24', verification_note='md-verified 2026-09-05 (§3.3.4 Probenahme und -transport, printed p.24 derived) [VC] — all three enum values printed; 24-h Mischprobe is "bevorzugt", Stichproben are "alternativ" permitted — gate REQ-07 blocks unless mischprobe_24h (STAGED S-4)', verified_at=now() where id='57a4444b-f43d-4394-a44d-4eb883364602' and verification_status not in ('verified_against_standard','corrected');
-- coliphagen_separat_gemessen
update public.fields set verification_status='verified_against_standard', verification_quote='Die gemäß EU-WasserWVVO vorgesehene Möglichkeit zur Verwendung der Referenzpathogene Campylobacter, Rotavirus und Cryptosporidium anstelle der in Tabelle 3 angegebenen Indikatororganismen ist in | Deutschland nicht zulässig. Für Coliphagen müssen abweichend zur EU-WasserWVVO sowohl somatische Coliphagen als auch F-spezifische Coliphagen separat gemessen und beurteilt werden. — printed p.23', verification_note='md-verified 2026-09-05 (§3.3.4 Auswahl der Indikatororganismen, printed p.23 derived; sentence spans a page break in the md) [VC] — "müssen … separat gemessen": hard, yet no gate (STAGED S-5)', verified_at=now() where id='2071c626-1efd-4475-a1ef-3009ee57900a' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-07 · Referenzanlagen-Dokumentation ########################
-- begutachtung_unabhaengig
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Daten müssen durch eine unabhängige Einrichtung oder die Genehmigungsbehörde nach 3.3.5 begutachtet werden. | Eine Referenzanlage im Sinne dieses Merkblatts ist eine Aufbereitungseinrichtung (entweder gesamter Aufbereitungszug oder Teil-Aufbereitungszug), 1. deren Leistungsfähigkeit für den gesamten Aufbereitungszug nach den Kriterien des umfänglichen Validierungsmonitorings nach Anhang C erfolgreich validiert oder für einen Teil-Aufbereitungszug, bei dem die Einhaltung der Leistungsziele mit geeigneter Vor- und Nachbehandlung, zu erwarten ist, festgelegt sowie von einer unabhängigen Einrichtung begutachtet wurde, und 2. die von einer autorisierten Stelle im Referenzanlage-Register online verfügbar gemacht wurde. — printed p.21 / p.24', verification_note='md-verified 2026-09-05 (§3.3.3 Planungsphase Alternativvariante + §3.3.5, printed p.21 / p.24 derived) [VC] — "müssen … begutachtet werden" applies to the Alternativvariante; is_required=true unconditionally (STAGED S-8); no gate (S-5)', verified_at=now() where id='d4a33a80-03f4-4c14-a677-79617b6f6177' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-09 · Filtrationsstufe — Auslegung ########################
-- filtrationsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Hierfür können unterschiedliche Arten von Filtrationsverfahren zum Einsatz kommen [...] Die bei der kommunalen Abwasserbehandlung und Wasseraufbereitung überwiegend eingesetzten Raumfilter lassen sich in Abhängigkeit der Durchströmungsgeschwindigkeit überschlägig in „schnelle“ und „langsame“ Filter einteilen. | Sandfilter wie auch Polstofffilter, Mikrosiebe sowie Raumfilter mit kompressiblem Filtermedium ermöglichen eine deutliche Reduktion des Feststoffgehalts nach einer Nachklärung | In der Abwassertechnik ist die Membrantechnik überwiegend als Membran-Bioreaktor-Verfahren (MBR-Verfahren) realisiert. | Mit Membranen deutlich geringerer Porengröße (Nanofiltration, Umkehrosmose) kann das Abwasser bis zur Trinkwasserqualität aufbereitet [...] Diese Membranen werden nicht beim Membran-Bioreaktor-Verfahren, sondern als separate Filtrationsstufe eingesetzt. — printed p.34–36', verification_note='md-verified 2026-09-05 (§5.2 incl. Membranfiltrationsverfahren; Bodenfilterverfahren from Tab. 5 p.33, printed p.34–36 derived) [VC] — enum values raumfilter "(Schnellsand)" and schnellsand overlap (STAGED S-6)', verified_at=now() where id='83ae33fd-8f1b-4844-9e7a-fe5b8b7838c5' and verification_status not in ('verified_against_standard','corrected');
-- helmintheneier_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Helmintheneier liegen im kommunalen Abwasser in Deutschland nur in sehr geringer Anzahl vor. Sie werden in der Vorklärung und in der Belebung größtenteils zurückgehalten. Dabei verbleibende Helmintheneier können in den Desinfektionsstufen unter praxisrelevanten Bedingungen nicht inaktiviert werden. Aufgrund der Filtrationswirkung und der Tatsache, dass Helmintheneier sehr gut an Quarz haften, kann jedoch sowohl die Schnell- als auch die Langsamsandfiltration einen ausreichenden Rückhalt der Helmintheneier erzielen, mit Konzentrationen von $\leqslant 1$ Ei je Liter im Ablauf. — printed p.34', verification_note='md-verified 2026-09-05 (§5.2, printed p.34 derived) [VC] — descriptive capability statement ("kann … erzielen"); the binding limit is Tab. 3 (intest_nematoden ws 06) — overlap (STAGED S-6)', verified_at=now() where id='8e9a7d67-d59b-44db-bedb-6ca1dda5c49e' and verification_status not in ('verified_against_standard','corrected');
-- flux_membran
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle E.1: Vorabzug einer Referenzanlage der Klasse A (Beispiel: Schweinfurt, siehe Anhang D.3) aus dem Referenzanlagen-Register samt Leistungsdaten und relevanten Betriebsparametern | Aufbereitungsstufe & Auslegungsparameter & Einzuhaltende Betriebsbedingungen | Keramische Ultrafiltration & Nominale Porengröße 30 nm , Flux $=90 \mathrm{l} / \mathrm{m}^{2} / \mathrm{h} \mathrm{bis} 120 \mathrm{l} / \mathrm{m}^{2} / \mathrm{h}$, Flockung mit Al ( $10 \mathrm{mg} / \mathrm{l}$ ), CEB (Frequenz ca. 2/Tag, NaOH + NaOCl $>\mathrm{HCl}+\mathrm{H}_{2} \mathrm{O}_{2}$ ) & Trübung im Filtrat $=(0,1 \mathrm{NTU}$ bis) 0,2 NTU (max.), Flux $\leqslant 120 \mathrm{l} / \mathrm{m}^{2} \mathrm{~h}$ | Bei der ..NSF 419"-Zertifizierung wird die minimale und mittlere $\log _{10}$-Reduktion für Viren bzw. Cryptosporidium mitsamt des maximal zugelassenen Permeatflusses angegeben. — printed p.85 / p.27', verification_note='md-verified 2026-09-05 (Tab. E.1 Keramische UF row + Tab. 4 MF/UF row, printed p.85 / p.27 derived) [VC] — CAVEAT: 90–120 l/m²/h is the Schweinfurt reference-plant window ("vorläufig", Weißdruck pending), not a printed limit; duplicates permeatfluss (ws 13) (STAGED S-6)', verified_at=now() where id='92b774ce-18b7-4bef-9859-63fd8438ddc0' and verification_status not in ('verified_against_standard','corrected');
-- filtergeschw_langsam
update public.fields set verification_status='verified_against_standard', verification_quote='In Schwellen- und Entwicklungsländern werden hingegen vermehrt die in der Trinkwasseraufbereitung etablierten Langsamsandfilter eingesetzt. Sie werden mit Filtergeschwindigkeiten von 0,05 $\mathrm{m} / \mathrm{h}$ bis $0,5 \mathrm{~m} / \mathrm{h}$ als letzte Verfahrensstufe der Abwasserbehandlung betrieben, um Bewässerungswasser bereitzustellen. Als einfache und kostengünstige Technologie ermöglichen sie eine Reduktion von Krankheitserregern bis zu 3 Log $_{10}$-Stufen (WHO 2006). [...] Richtlinien für die Auslegung und den Betrieb von Langsamsandfiltern liegen in Deutschland nur für die Aufbereitung von Trinkwasser vor (Arbeitsblatt DVGW W 213-4 (A)). — printed p.34', verification_note='md-verified 2026-09-05 (§5.2, printed p.34 derived) [VC] — descriptive operating range (standard_range, SR-2), design rules deferred to DVGW W 213-4 (NR)', verified_at=now() where id='e8bb586a-a6c0-429a-b5f4-e1b092a13771' and verification_status not in ('verified_against_standard','corrected');
-- filtergeschw_schnellsand
update public.fields set verification_status='verified_against_standard', verification_quote='Die Schnellsandfiltration wird typischerweise bei Filtergeschwindigkeiten zwischen $5 \mathrm{~m} / \mathrm{h}$ und $15 \mathrm{~m} / \mathrm{h}$ betrieben. Zu Untersuchungen an Drucksandfiltern werden beispielsweise eine Reduktion von E. coli von $0,18 \log _{10}$-Stufen bzw. $34 \%$ bei einer Filtergeschwindigkeit von $5 \mathrm{~m} / \mathrm{h}$ berichtet (Gomez et al. 2006) und für die Sandfiltration im Anschluss an die Nachklärung eine vergleichbare Eliminationsleistung von $0,21 \log _{10}$-Stufen bzw. $38 \%$ bei einer Filtergeschwindigkeit von $14 \mathrm{~m} / \mathrm{h}$ (AbeggLen et al. 2009). — printed p.34', verification_note='md-verified 2026-09-05 (§5.2, printed p.34 derived) [VC] — "typischerweise" 5–15 m/h: descriptive range (standard_range, SR-2); design per DWA-A 203 (NR)', verified_at=now() where id='bc999811-619f-49d3-81b3-7207b0c57e12' and verification_status not in ('verified_against_standard','corrected');
-- mbr_porendurchmesser
update public.fields set verification_status='verified_against_standard', verification_quote='In der Abwassertechnik ist die Membrantechnik überwiegend als Membran-Bioreaktor-Verfahren (MBR-Verfahren) realisiert. Die Membranfiltration ersetzt dabei die konventionelle Nachklärung zur Abtrennung des belebten Schlamms. [...] Mit üblichen Trenngrenzen von $0,1 \mu \mathrm{~m}$ bis $0,02 \mu \mathrm{~m}$ lassen sich neben Feststoffen auch Bakterien, Kolloide, Helmintheneier und zum Teil Viren zurückhalten. | In Membranbelebungsanlagen erfolgt aufgrund der üblichen Porenweite bis ca. $0,02 \mu \mathrm{~m}$ keine gezielte Spurenstoffelimination. — printed p.35', verification_note='md-verified 2026-09-05 (§5.2 Membranfiltrationsverfahren, printed p.35 derived) [VC] — "übliche Trenngrenzen": descriptive range, not a limit', verified_at=now() where id='75493198-1c44-4994-98f1-705b77e8c00e' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-10 · Spurenstoffstufe — Auslegung ########################
-- bettvolumen_durchgesetzt
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderliche Dosiermenge der Aktivkohle (bei der GAK entsprechend dem durchsetzbaren Bettvolumen (BV) oder einer umgerechneten „Carbon-usage-rate“) hängt unter anderem von der Bindungsaffinität des zu entfernenden Stoffs an das Adsorbens ab. | Bei der GAK-Adsorption gibt es mittlerweile Erfahrungen zu möglichen Standzeiten bis zur Erreichung eines Durchbruchkriteriums für Spurenstoffe, Kontaktzeiten im GAK-Filter (BENSTÖM 2017) und den Betriebstechniken | Tabelle B. 1 (fortgesetzt) | $0,6 \mathrm{~g} \mathrm{O}_{3} / \mathrm{g}$ DOC, HRT in $\mathrm{O}_{3}=20 \mathrm{~min}$ (Design], EBCT in BAK = 25 min , 0 bis 35000 Bettvolumen & Schweinfurt & Ozon mit BAK-Filter (Pilot) — printed p.38 / p.60–71', verification_note='md-verified 2026-09-05 (§5.3 Adsorptive Verfahren + Tab. B.1 Ozon/BAK Schweinfurt row, printed p.38 / Tab. B.1 p.60–71 (row ≈ p.66 interpolated) derived) [VC] — clause says "Anhang E" but Tab. E.1 prints no BV figure; the 0–35000 BV value is Tab. B.1 (STAGED S-1); dimensioning deferred to DWA-M 285-2 (NR)', verified_at=now() where id='c40016d6-65a3-459b-b466-fd09d56b1579' and verification_status not in ('verified_against_standard','corrected');
-- ebct_bak_filter
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle E. 1 (Ende) | Biologisch aktiver GAK-Filter (2-stufig) & - & (min.) EBCT $=25 \mathrm{~min}$ | EBCT & Leerbettkontaktzeit | EBCT in BAK = 25 min , 0 bis 35000 Bettvolumen & Schweinfurt & Ozon mit BAK-Filter (Pilot) | Leerbettkontaktzeit BAK-Filter ca. 30 min , UF-Desinfektion Fluenz: ca. $400 \mathrm{~J} \cdot \mathrm{~m}^{-2}$, Anlage wird ganzjährig betrieben. — printed p.86 / p.60 / p.60–71 / p.82', verification_note='md-verified 2026-09-05 (Tab. E.1 Einzuhaltende Betriebsbedingungen + Tab. B.1 Legende/row + D.3, printed p.86 / p.60 / p.82 derived) [VC] — CAVEAT: (min.) 25 min is the Schweinfurt reference-plant condition ("vorläufig"); D.3 prints "ca. 30 min" for the same plant — internal inconsistency in the draft', verified_at=now() where id='71a10f4e-5e86-4fa4-95c7-2f195b2608a5' and verification_status not in ('verified_against_standard','corrected');
-- pak_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderlichen Dosierungen sind von der organischen Hintergrundmatrix abhängig, die in Konkurrenz zu den Spurenstoffen an der Aktivkohle adsorbieren kann, und liegen bei Verwendung von Pulveraktivkohle typischerweise im Bereich von 1 mg PAK/mg DOC bis 2 mg PAK/mg DOC (Merkblatt DWA-M 285-2:2021). — printed p.38', verification_note='md-verified 2026-09-05 (§5.3 Adsorptive Verfahren, printed p.38 derived) [VC] — "typischerweise" 1–2 mg PAK/mg DOC: descriptive range (standard_range, SR-2), sourced to DWA-M 285-2', verified_at=now() where id='e523c073-5bb5-48e3-83b1-9577e018689d' and verification_status not in ('verified_against_standard','corrected');
-- nf_uo_konzentratstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Wasserwiederverwendung mit hohen Qualitätszielen ist auch der Einsatz dichter Membranverfahren wie Nanofiltration (NF) und Umkehrosmose (UO) eine Option. Diese Membranen sind in der Lage, gelöste Stoffe (z. B. Salze und organische Stoffe) sowie Viren und Resistenzgene weitgehend und unspezifisch zurückzuhalten. Bei der NF/UO-Behandlung muss mit einem Konzentratstrom von $15 \%$ bis $20 \%$ des Eingangsstroms gerechnet werden. — printed p.38', verification_note='md-verified 2026-09-05 (§5.3 Physikalische Verfahren/Membranverfahren, printed p.38 derived) [VC] — "muss … gerechnet werden": planning assumption range 15–20 % (standard_range, SR-2)', verified_at=now() where id='bb9e4de7-3f22-4d7e-992c-e45d2e49f137' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-11 · Desinfektionsstufe — Auslegung ########################
-- perameisensaeure_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Für eine weitgehende Reduktion von Bakterien und Coliphagen reicht Perameisensäure in Konzentrationen von $5 \mathrm{mg} / \mathrm{l} \mathrm{bis} 6 \mathrm{mg} / \mathrm{l}$ mit Reaktionszeiten von 5 min bis 45 min aus, um Bakterien und Coliphagen (Viren, die bestimmte Bakterien befallen) zufriedenstellend zu reduzieren. F+-Bakteriophagen, sporenbildende Bakterien wie Clostridium perfringens sowie parasitäre Protozoen (Cryptosporidium, Giardia) hingegen sind deutlich resistenter bis nicht zu eliminieren. Großtechnische Untersuchungen auf Kläranlagen zeigten eine Bakterien-Reduktion um $2 \log _{10}$ - bis $3 \log _{10}$-Stufen, zum Teil nach 6 min bis 10 min Reaktionszeit mit 15 ppm bis 20 ppm Perameisensäure (GnIRSS et al. 2015, Maya et al. 2012, GEHR et al. 2009). — printed p.44–45', verification_note='md-verified 2026-09-05 (§5.4.3 Persäuren, printed p.44–45 derived) [VC] — descriptive range (standard_range, SR-2); Tab. B.1 prints 2,0–20 mg/l PAS rows', verified_at=now() where id='8cf0df0a-9ca4-4f70-a933-fa0ee6cafb6c' and verification_status not in ('verified_against_standard','corrected');
-- uv_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Bakterien wie E. coli, die das Enzym Photolyase besitzen, scheint Photoreaktivierung jedoch kein kritischer Prozess zu sein, solange die Bestrahlungsdosis größer als $40 \mathrm{~mJ} / \mathrm{cm}^{2}\left(=400 \mathrm{~J} / \mathrm{m}^{2}\right)$ ist. Die empfohlene UV-Dosis zur Desinfektion von behandeltem Abwasser liegt von $30 \mathrm{~mJ} / \mathrm{cm}^{2}$ bis $45 \mathrm{~mJ} / \mathrm{cm}^{2}$ (Merkblatt DWA-M 205:2013) bis zu $100 \mathrm{~mJ} / \mathrm{cm}^{2}$ (nach NWRI 2012). Bei $40 \mathrm{~mJ} / \mathrm{cm}^{2}$ lassen sich Bakterien- sowie Coliphagenkonzentrationen im behandelten Abwasser bis unter die Bestimmungsgrenze reduzieren lum rund $4 \log _{10}$ - bzw. 2 Log $_{10}$-Stufen) (BISCHOFF 2013). — printed p.41', verification_note='md-verified 2026-09-05 (§5.4.3 UV-Bestrahlung, printed p.41 derived) [VC] — "empfohlene" 30–45 up to 100 mJ/cm²: recommendation range (standard_range, SR-2); Tab. E.1 Schweinfurt 400–500 J/m²', verified_at=now() where id='b9dfeb45-db1f-442e-81ed-a1a4ba79c638' and verification_status not in ('verified_against_standard','corrected');
-- ozon_dosis_spez
update public.fields set verification_status='verified_against_standard', verification_quote='In der Regel wird die Desinfektionswirkung (wie auch die Entfernung von Spurenstoffen) in Abhängigkeit der spezifischen Ozondosis angegeben (siehe Tabellen B. 1 und B. 2 in Anhang B). Spezifische Ozondosen von $0,5 \mathrm{~g}$ bis $1,0 \mathrm{~g} \mathrm{O}_{3} / \mathrm{g}$ DOC sind üblich. Dabei erfolgt die Angabe als Nitrit-korrigierter DOC-Wert, da Nitrit eine stark Ozon-zehrende Substanz ist | Typische Dosierungen für die Spurenstoffentfernung (im Mittel $80 \%$ Entfernung ausgewählter Leitsubstanzen) liegen um $0,5 \mathrm{mg} \mathrm{O}_{3} / \mathrm{mg}$ DOC bis $1 \mathrm{mg} \mathrm{O}_{3} / \mathrm{mg}$ DOC. — printed p.42 / p.36', verification_note='md-verified 2026-09-05 (§5.4.3 Ozonung + §5.3 Oxidative Verfahren, printed p.42 / p.36 derived) [VC] — "üblich"/"typische" 0,5–1,0 g O3/g DOC: descriptive range (standard_range, SR-2), Nitrit-korrigiert', verified_at=now() where id='5aabf687-6325-49a9-8fd5-a7796e0bc38e' and verification_status not in ('verified_against_standard','corrected');
-- desinfektionsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Desinfektion: Gemäß EU-WasserWVVO ist für alle Wassergüteklassen eine Desinfektion gefordert. Erläuterungen zu Desinfektionsverfahren siehe 5.4. | Grundsätzlich ist der Einsatz verschiedener Desinfektionsverfahren möglich, sofern mit diesen die gemäß Tabelle 3 vorgegebenen Anforderungen und Leistungsziele über die gesamte Aufbereitungskette erreicht werden. Gängige Desinfektionsverfahren sind im Folgenden aufgeführt. | Membranfiltration | UV-Bestrahlung | Ozonung | Chlor und Chlordioxid als Desinfektionsmittel | Persäuren (Peroxycarbonsäuren) | Wasserstoffperoxid | Desinfektion mit Silberionen oder Titandioxid ist wegen der metallenen Mikroschadstoffe bzw. Nanopartikel nicht zu empfehlen. — printed p.32 / p.40–45', verification_note='md-verified 2026-09-05 (§5.1 Erläuterung 4 + §5.4.3 section heads, printed p.32 / p.40–45 derived) [VC] — all eight enum values are printed §5.4.3 methods; Chlor/ClO2 printed as Restdesinfektion only (DIN 19650 §5.2)', verified_at=now() where id='5b647bfc-7a8f-4292-9aae-c77415f0d5d0' and verification_status not in ('verified_against_standard','corrected');
-- ct_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Die Effizienz von chemischen Desinfektionsprozessen kann mit dem sogenannten Ct-Konzept beschrieben werden. Das Ct-Konzept bedient sich der vereinfachten Annahme, dass für die sichere Desinfektion das Produkt aus (Rest-)Desinfektionsmittelkonzentration $(C)$ und Kontaktzeit $(t)$ einen bestimmten Wert erreichen muss (BISCHOFF 2013). Dieses Produkt ( $C \cdot t$ ) ergibt den Ct-Wert in ( $\mathrm{mg} \cdot \mathrm{min}$ )/l (Hembach 2021). Analoges gilt für die UV-Desinfektion. | Ct-Wert & Produkt aus Restkonzentration des Desinfektionsmittels bzw. UV-Dosis und Einwirkzeit — printed p.40 / p.12', verification_note='md-verified 2026-09-05 (§5.4.1 + Tab. 1, printed p.40 / p.12 derived) [VC] — the md prints the definition only; no numeric target except Tab. B.2 Chlor "≥ 15 mg·min/l" (p.73); §5.4.3 says the Ct concept is in der Regel NOT applicable to German ozonation', verified_at=now() where id='74a4e385-b121-449d-abbb-ecaf41a1d1ff' and verification_status not in ('verified_against_standard','corrected');
-- uv_dosis_referenz
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4 (fortgesetzt) | UV-Desinfektion & Inaktivierung der DNA-Replikationsfähigkeit von Mikroorganismen durch UV-Bestrahlung & Durchflussrate, Bestrahlungsdosis, UV-Transmission des Wassers & Prävalidierung: Erfolgt in der Regel durch den Hersteller gemäß DVGW W 294 (nicht für Viren) bzw. der EPAGuideline. Nachweis einer Referenzdosis $\geqslant 40 \mathrm{~mJ} / \mathrm{cm}^{2}$, Definition der erforderlichen Betriebsparameter, Zuordnung von $\log _{10}$-Reduktionen in Abhängigkeit von der UV-Transmission. | solange die Bestrahlungsdosis größer als $40 \mathrm{~mJ} / \mathrm{cm}^{2}\left(=400 \mathrm{~J} / \mathrm{m}^{2}\right)$ ist — printed p.27 / p.41', verification_note='md-verified 2026-09-05 (Tab. 4 UV-Desinfektion row + §5.4.3, printed p.27 / p.41 derived) [VC] — the encode-time quote "Nachweis einer Referenzdosis ≥ 40 mJ/cm² (=400 J/m²) nach DVGW W 294-1" conflates Tab. 4 (Referenzdosis) with §5.4.3 (=400 J/m² photoreactivation threshold); clause retag to Tab. 4 (STAGED S-1)', verified_at=now() where id='44e8491f-b0ce-412e-b143-51db33952dd8' and verification_status not in ('verified_against_standard','corrected');
-- clo2_restkonz
update public.fields set verification_status='verified_against_standard', verification_quote='Ab einer Restchlordioxidkonzentration von $0,4 \mathrm{mg} / \mathrm{l}$ (bei einer Chlordioxiddosis von $4 \mathrm{mg} / \mathrm{l}$ ) wurde die Bestimmungsgrenze unterschritten. Für Chlordioxid ist eine Restchlordioxidkonzentration von $0,2 \mathrm{mg} / \mathrm{l}$ ausreichend, um eine Inaktivierung von E. coli um mindestens 3 Log $_{10}$-Stufen zu erzielen (BISCHOFF 2013). | Daher sollte die Desinfektion mit chlorhaltigen Mitteln und Chlordioxid, ähnlich dem Ansatz bei der Trinkwasserversorgung, einzig als Restdesinfektion und zur Verhinderung von Wiederverkeimung bei längeren Transport- und Speicherdauern eingesetzt werden. Dabei ist Chlordioxid das Desinfektionsmittel der Wahl. — printed p.44 / p.43', verification_note='md-verified 2026-09-05 (§5.4.3 Chlor und Chlordioxid, printed p.44 / p.43 derived) [VC] — literature values (BISCHOFF 2013), not printed limits', verified_at=now() where id='b6236b56-58fd-472b-a136-230937d76854' and verification_status not in ('verified_against_standard','corrected');
-- reaktor_hydraulik_charakterisiert
update public.fields set verification_status='verified_against_standard', verification_quote='Nachweis des Ct-Werts in der großtechnischen Anlage: hydraulische Charakterisierung (Verweilzeitverteilung) des Desinfektionsreaktors, ggf. durch Strömungssimulation und/oder Tracer-Versuch. | Der Reaktor muss hydraulisch charakterisiert sein durch Strömungssimulationen und/oder Tracer-Versuche. Die Einflussfaktoren sind im Betrieb auf geeignete Weise zu überwachen. — printed p.27', verification_note='md-verified 2026-09-05 (Tab. 4 rows Chlorbasierte Desinfektion + Ozonbasierte Desinfektion, printed p.27 derived) [VC] — clause "§5.4.1" does not contain this; it is Tab. 4 (§3.3.6) (STAGED S-1); "muss" for ozone reactors, no gate (S-5)', verified_at=now() where id='35b12960-adbc-4e2e-8550-665acb8ed126' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-12 · Verfahrensketten-Auswahl ########################
-- verfahrenskette
update public.fields set verification_status='verified_against_standard', verification_quote='Insbesondere die Einhaltung der Qualitätsanforderungen in Bezug auf die mikrobiologischen Parameter und zur Validierung der Reduktion von Pathogenen (z. B. 6 Log $_{10}$-Stufen für die Entfernung von Viren) sowie gegebenenfalls zusätzliche Anforderungen an die Spurenstoffelemination können nur durch eine Kombination von mehreren Verfahrensstufen erreicht werden. In Bild 7 werden exemplarisch mögliche Verfahrensketten dargestellt und die damit theoretisch erzielbaren $\log _{10}$-Reduktionen von Pathogenen angegeben. | Die Reihenfolge der Aufbereitungsschritte hängt von den verfahrenstechnischen Randbedingungen ab und ist in Bild 4 nur beispielhaft dargestellt. In der Praxis sind vielfältige Kombinationen der Verfahrensstufen möglich, um die geforderten Qualitätsanforderungen an das aufbereitete Wasser zu erfüllen. — printed p.46 / p.32', verification_note='md-verified 2026-09-05 (§5.5 + §5.1, printed p.46 / p.32 derived) [VC] — free text for a printed stage list (Bild 4: Mech.-biol. + Filtration + Weitere Aufbereitung + Desinfektion) → selection widget candidate (STAGED S-10)', verified_at=now() where id='e8c23f61-df2b-4e53-a244-3dff18abb89a' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-13 · Betriebsmonitoring & Störfallmanagement ########################
-- reinigungskonzept
update public.fields set verification_status='verified_against_standard', verification_quote='Unter anderem folgende Aspekte sollten bei der Ausgestaltung des Speichers berücksichtigt werden: | bei allen Bauformen sollte ein Notüberlauf oder/und eine Umgehung vorgesehen werden, | die Möglichkeit einer Reinigung ist insbesondere für einen langfristigen Betrieb wesentlich, | die Zugänglichkeit für Betriebspersonal ist unter Einhaltung der entsprechenden Arbeitsschutzanforderungen zu gewährleisten. Ebenso ist der Zugang für Unbefugte zu verhindern, — printed p.56', verification_note='md-verified 2026-09-05 (§7.3 Bauformen, printed p.56 derived) [VC] — clause_reference is NULL in prod → §7.3 (STAGED S-1); a storage field sitting on the monitoring worksheet (S-9)', verified_at=now() where id='96e705f1-4422-4ece-8a48-c91c4c9f0453' and verification_status not in ('verified_against_standard','corrected');
-- messhauefigkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Messhäufigkeit von Betriebsparametern muss die Systemträgheit berücksichtigen. | Tabelle 6 zeigt beispielhaft Messhäufigkeiten zur Überprüfung des Betriebszustands einzelner Aufbereitungsstufen. | Tabelle 6: Beispiel für Betriebsparameter und deren Messhäufigkeit zur Überwachung der zulässigen Betriebsbedingungen von ausgewählten Aufbereitungsstufen | Aufbereitungsstufe & Betrieblicher Überwachungsparameter & Messhäufigkeit | Medienfiltration & Trübung, Durchfluss & Online | Umkehrosmose (RO) & Elektrische Leitfähigkeit oder TOC oder DOC & Online | UV-Desinfektion (UV) & UV-Intensität, UV-Transmission, Durchfluss & Online | Chlorung $\left(\mathrm{Cl}_{2}\right)$ & Freies Restchlor und Kontaktzeit, pH-Wert, Temperatur & Online oder zumindest täglich — printed p.51–52', verification_note='md-verified 2026-09-05 (§6.4 + Tab. 6, printed p.51–52 derived) [VC] — Tab. 6 is explicitly a "Beispiel" (Quelle: Australian Guidelines); printed frequencies are Online / Täglich / Wöchentlich — enum value monatlich is EKOWAI-added; is_required=true and gate REQ-11 blocks unless online (STAGED S-4 / S-8)', verified_at=now() where id='9ac3c53f-de43-4a56-be3c-af1fed36d682' and verification_status not in ('verified_against_standard','corrected');
-- perzentil_konformitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 3 müssen in mindestens $90 \%$ der Proben eingehalten werden. | Für die Qualitätsüberwachung ist angelehnt an die EU-WasserWVVO, Anhang 1, Abschnitt 2, weiterhin gefordert, dass $90 \%$ der Proben die Mindestanforderungen gemäß Tabelle 3 einhalten müssen und die weiteren Proben eine maximale Überschreitung von $1 \log _{10}$-Stufe für E. coli und Legionellen bzw. $100 \%$ für andere Parameter aufweisen dürfen. Dies gilt vorbehaltlich gegebenenfalls weiterergehender Anforderungen, die aus dem Risikomanagementplan resultieren. — printed p.15 / p.51', verification_note='md-verified 2026-09-05 (§3.1 + §6.4, printed p.15 / p.51 derived) [VC] — standard_fixed 90 % that is hand-enterable, so gate REQ-03 "perzentil_konformitaet >= 90" is a tautology once the engineer types the printed constant (STAGED S-4 / S-10, #22 class)', verified_at=now() where id='fe143fcf-165e-465b-a0a2-6f513d9692aa' and verification_status not in ('verified_against_standard','corrected');
-- uv_transmission
update public.fields set verification_status='verified_against_standard', verification_quote='UV-Desinfektion (UV) & UV-Intensität, UV-Transmission, Durchfluss & Online | Eine wichtige Einflussgröße auf die erreichbare Strahlungsstärke und die Wirtschaftlichkeit der UVBestrahlung ist die UV-C-Durchlässigkeit des Abwassers. | UV-Desinfektion & UV-Dosis $=400 \mathrm{~J} / \mathrm{m}^{2}$ bis $500 \mathrm{~J} / \mathrm{m}^{2}$ & Trübung $=0,3 \mathrm{NTU}$ bis 1,1 NTU, UV-Transmission = $94 \% / \mathrm{cm}$ bis $99 \% / \mathrm{cm}$, (max. Durchfluss) — printed p.52 / p.41 / p.86', verification_note='md-verified 2026-09-05 (Tab. 6 UV row + §5.4.3 + Tab. E.1 UV row, printed p.52 / p.41 / p.86 derived) [VC] — CAVEAT: 94–99 %/cm is the Schweinfurt reference window ("vorläufig"), not a limit', verified_at=now() where id='cfd48aff-b6e0-41f7-b5e2-1754c6cd421c' and verification_status not in ('verified_against_standard','corrected');
-- delta_sak254
update public.fields set verification_status='verified_against_standard', verification_quote='Die Prozesssteuerung der Ozonung ist über die relative Reduktion des $\mathrm{SAK}_{254}\left(\triangle \mathrm{SAK}_{254}\right)$ gebräuchlich. Im Gegensatz zur Ozonung in einigen anderen Ländern, wie zum Beispiel Australien oder USA, wird die Ozonung in Deutschland in der Regel so betrieben, dass keine Restozon-Konzentration gemessen werden kann, und damit das Ct-Konzept nicht angewendet werden kann. | Ozonung/Biologisch aktiver GAK-Filter (Ozon/BAK) & Spezifische Ozondosis oder $\triangle \mathrm{SAK}_{254}$ Temperatur, pH, Trübung — printed p.42 / p.52', verification_note='md-verified 2026-09-05 (§5.4.3 Ozonung + Tab. 6 Ozon/BAK row, printed p.42 / p.52 derived) [VC] — Tab. B.1 prints design values 34 % / 47 % (Braunschweig, Berlin-Schönerlinde)', verified_at=now() where id='173bbce9-5f73-4d5f-b305-2c6cd2a0bacf' and verification_status not in ('verified_against_standard','corrected');
-- transmembrandruck
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 6: Beispiel für Betriebsparameter und deren Messhäufigkeit zur Überwachung der zulässigen Betriebsbedingungen von ausgewählten Aufbereitungsstufen | Membran-Bioreaktor (MBR) & pH-Wert, Sauerstoff im Bioreaktor, Transmembrandruck, Durchfluss, Trübung Schlammalter, hydraulischer Verweilzeit, Trockensubstanz (TS) im Belebungsbecken | Membraneigenschaften (Porendurchmesser, Oberflächenladung, Hydrophobizität), Membranmodul, Betriebsbedingungen (z. B. Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung) — printed p.52 / p.27', verification_note='md-verified 2026-09-05 (Tab. 6 MBR row + Tab. 4 MF/UF Einflussfaktoren, printed p.52 / p.27 derived) [VC] — online MBR parameter; no printed numeric limit', verified_at=now() where id='d95a643f-43a4-4064-a021-674895351325' and verification_status not in ('verified_against_standard','corrected');
-- permeatfluss
update public.fields set verification_status='verified_against_standard', verification_quote='Mikrofiltration und Ultrafiltration & Rückhalt durch dichte trennaktive Schicht der porösen Membranen [...] & Membraneigenschaften (Porendurchmesser, Oberflächenladung, Hydrophobizität), Membranmodul, Betriebsbedingungen (z. B. Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung) [...] Bei der ..NSF 419"-Zertifizierung wird die minimale und mittlere $\log _{10}$-Reduktion für Viren bzw. Cryptosporidium mitsamt des maximal zugelassenen Permeatflusses angegeben. Im Betrieb ist die Integrität fortlaufend oder zumindest regelmäßig zu überwachen. | Mikro- oder Ultrafiltration (MF/UF) | Integritätsmessung (z. B. Druckhaltetest) — printed p.27 / p.52', verification_note='md-verified 2026-09-05 (Tab. 4 MF/UF row + Tab. 6 MF/UF row, printed p.27 / p.52 derived) [VC] — CAVEAT: the description "Online-Durchfluss MF/UF gemäß Tabelle 6" is NOT supported: Tab. 6 MF/UF row lists Trübung + Integritätsmessung only (Durchfluss appears in the MBR/Medienfiltration/UV rows); the Permeatfluss anchor is Tab. 4; duplicates flux_membran ws 09 (STAGED S-1 / S-6)', verified_at=now() where id='58d5d015-f3b3-4ed6-bfa5-dd0f4623d6eb' and verification_status not in ('verified_against_standard','corrected');
-- restchlor_freies
update public.fields set verification_status='verified_against_standard', verification_quote='Chlorung $\left(\mathrm{Cl}_{2}\right)$ & Freies Restchlor und Kontaktzeit, pH-Wert, Temperatur & Online oder zumindest täglich | Ein Ct-Wert, der mit einer Inaktivierung von $4 \log _{10}$-Stufen für Viren lund Bakterien) verbunden ist, beträgt $\geqslant 15 \mathrm{mg} \cdot \mathrm{min} / \mathrm{l}(\mathrm{d} . \mathrm{h} .0,5 \mathrm{mg} / \mathrm{l}$ für 30 min$)$ bei einem pH -Wert $\leqslant 7,5$ und einer Temperatur von $\geqslant 10^{\circ} \mathrm{C}$. — printed p.52 / p.73', verification_note='md-verified 2026-09-05 (Tab. 6 Chlorung row + Tab. B.2 Chlor row, printed p.52 / p.73 derived) [VC] — chlorine printed as Restdesinfektion only (§5.4.3 p.43); Tab. B.2 value is the Australian guideline figure, indicative', verified_at=now() where id='5e203da0-a355-44b0-a9c7-cf8309419273' and verification_status not in ('verified_against_standard','corrected');
-- alarm_verzoegerung_min
update public.fields set verification_status='verified_against_standard', verification_quote='Durch Online-Monitoring von relevanten Betriebsparametern sind der Betriebszustand und die Einhaltung der Anforderungen zu allen Zeitpunkten sicherzustellen und Abweichungen vom zulässigen Betriebsfenster oder Havarien frühzeitig festzustellen, um Gegenmaßnahmen einzuleiten. Die Mess-wertaktualisierung/-abfrage sollte in der Regel wenige Minuten nicht überschreiten beziehungsweise die Systemträgheit widerspiegeln, um rechtzeitig Gegenmaßnahmen einzuleiten. Abweichungen vom zulässigen Betriebsfenster sollten je nach System nach 5 min bis 30 min eine Alarmierung auslösen. — printed p.51', verification_note='md-verified 2026-09-05 (§6.4, printed p.51 derived) [VC] — "sollten … 5 min bis 30 min": recommendation range; gate REQ-11 BLOCKS on ≤ 30 (STAGED S-4 block→warn)', verified_at=now() where id='900ea80a-ec7c-441f-a8e6-b75e94664a61' and verification_status not in ('verified_against_standard','corrected');
-- notueberlauf
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Speicher selbst sind verschiedene Bauformen denkbar, die sich vor allem durch das gewählte Baumaterial (Beton, Kunststoffdichtung etc.) und die Ausführung (offen, abgedeckt) unterscheiden. [...] Unter anderem folgende Aspekte sollten bei der Ausgestaltung des Speichers berücksichtigt werden: | bei allen Bauformen sollte ein Notüberlauf oder/und eine Umgehung vorgesehen werden, | die Möglichkeit einer Reinigung ist insbesondere für einen langfristigen Betrieb wesentlich, — printed p.56', verification_note='md-verified 2026-09-05 (§7.3 Bauformen, printed p.56 derived) [VC] — "sollte": recommendation (warn REQ-13 fits); clause_reference is NULL in prod → §7.3 (STAGED S-1); storage field on the monitoring worksheet (S-9)', verified_at=now() where id='5d066d07-2d87-44db-83b3-222f13eb2f2b' and verification_status not in ('verified_against_standard','corrected');
-- redundanz_konzept
update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufbereitungseinrichtungen für die Wasserwiederverwendung müssen in allen Bereichen die sichere Einhaltung der gesetzlichen und vertraglichen Anforderungen gewährleisten. Redundanzen in Aufbereitungsanlagen zur Wasserwiederverwendung sind auf allen Ebenen zu bedenken. Redundanzen im Hinblick auf das Risikomanagement sind großteils schon in der Planung durch die Auslegung als Multi-Barrieren-Systeme zu berücksichtigen und werden in Abschnitt 5 ausführlich dargestellt. Von besonderer betrieblicher Bedeutung sind folgende Fragestellungen: - technische Redundanzen (engl. „Duty-standby“), - alternative Ressourcen (z. B. Bereitstellung von Grundwasser im Falle von Anlagenstörungen), - vertragliche Regelungen (z. B. keine Zusage einer 24/7-Verfügbarkeit des aufbereiteten Wassers). | Die Redundanzen können dabei sowohl in qualitativer als auch quantitativer Hinsicht erforderlich sein. — printed p.53', verification_note='md-verified 2026-09-05 (§6.5 Redundanzen, printed p.53 derived) [VC] — "sind … zu bedenken": obligation to consider; boolean fits; no gate (S-5 note)', verified_at=now() where id='d9992106-a5ce-43fe-aac4-163f8080f5f7' and verification_status not in ('verified_against_standard','corrected');
-- messhauefigkeit_integritaet
update public.fields set verification_status='verified_against_standard', verification_quote='Mikro- oder Ultrafiltration (MF/UF) | Integritätsmessung (z. B. Druckhaltetest) | Im Betrieb ist die Integrität fortlaufend oder zumindest regelmäßig zu überwachen. Verschiedene Integritätstests können kontinuierlich (z. B. Trübungsmessung oder Partikelzählung im Permeat) oder diskontinuierlich (z. B. Druckhaltetest, Blasentest oder Spiking-Test) durchgeführt werden. — printed p.52 / p.27', verification_note='md-verified 2026-09-05 (Tab. 6 MF/UF row — Integritätsmessung "Täglich" — + Tab. 4 MF/UF Validierungsmethodik, printed p.52 / p.27 derived) [VC] — Tab. 6 is a "Beispiel"; enum value monatlich is EKOWAI-added; worksheet M12002-23 (Membranintegritätsprüfung) has no fields while this one sits on ws 13 (STAGED S-9)', verified_at=now() where id='ee41092b-cf9c-40b9-af0e-3f80fe72c444' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-14 · Speicherung & Transport — Auslegung ########################
-- ausgleichsvolumen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Berechnung des Speichervolumens entspricht der herkömmlichen Speicherberechnung. Es ist das Ausgleichsvolumen und gegebenenfalls ein Sicherheitsvorrat zur Überbrückung von Betriebsstörungen zu berücksichtigen. Ziel ist es, dass der Speicher den Wasserbedarf zu jedem Zeitpunkt deckt, in denen eine Bewässerung notwendig ist. Das ist nur möglich, wenn der Zufluss, also das anfallende aufbereitete Wasser in Summe über dem Bedarf liegt. | Das erforderliche Ausgleichsvolumen ist von | dem Zeitraum, über den beabsichtigt ist, den Ausgleich vorzunehmen (Tages-, Wochen-, Monatsausgleich), | dem Wasserzufluss, und | der Wasserentnahme | abhängig. — printed p.56–57', verification_note='md-verified 2026-09-05 (§7.4 Bemessung, printed p.56–57 derived) [VC] — the md prints NO formula (Zufluss-/Entnahmeganglinien method only); no equation exists, none proposed', verified_at=now() where id='6eb4906c-15d0-4d9f-85f3-782fc3f32877' and verification_status not in ('verified_against_standard','corrected');
-- sekundaerdesinfektion_erforderlich
update public.fields set verification_status='verified_against_standard', verification_quote='Unter bestimmten Umständen kann es sinnvoll bzw. erforderlich sein, eine Sekundärdesinfektion in das weitere Transport- bzw. Verteilungsnetz zu integrieren. Dies ist im Rahmen des Risikomanagementplans zu prüfen, beispielsweise für die Wassernutzung nach einer Speicherung des aufbereiteten Wassers, da die Stagnation den Mikroorganismen die Zeit für Regeneration und Vermehrung bietet. | in Abhängigkeit von der Speicherdauer und den festgelegten Qualitätsanforderungen an das Wasser kann aufgrund der Wiederverkeimung des aufbereiteten Wassers eine zusätzliche Desinfektion nach der Speicherung erforderlich werden. Dies ist im Risikomanagementplan entsprechend zu berücksichtigen. — printed p.40 / p.56', verification_note='md-verified 2026-09-05 (§5.4.2 + §7.3, printed p.40 / p.56 derived) [VC] — "kann … erforderlich sein / ist … zu prüfen": RMP decision; warn gate REQ-12 fits', verified_at=now() where id='9b7748e2-5bb5-48a3-92d8-8bae21a32b32' and verification_status not in ('verified_against_standard','corrected');
-- rohrfarbe
update public.fields set verification_status='verified_against_standard', verification_quote='Der Leitungsverlauf zwischen Aufbereitungseinrichtung und Speicher sollte, ebenso wie der weitere Verlauf ab dem Speicher, dokumentiert und in einem Planwerk festgehalten werden (siehe Merkblatt DWA-M 1200-3:2025). Idealerweise wird der Verlauf auch vor Ort gekennzeichnet. | Gemäß internationalen Regelungen erfolgt eine Farbgebung der technischen Bauteile, wie Rohre, Emitter etc., in violetter Farbe (siehe ISO 16075-3 und Merkblatt DWA-M 1200-3:2025 in 5.1.4). — printed p.55–56', verification_note='md-verified 2026-09-05 (§7.2 Transport des Wassers zum Speicher, printed p.55–56 derived) [VC] — "Gemäß internationalen Regelungen erfolgt": descriptive reference to ISO 16075-3 (NR); enum value andere is EKOWAI''s non-conforming option', verified_at=now() where id='8302e520-a5f4-4a84-95b7-90d78e344a52' and verification_status not in ('verified_against_standard','corrected');
-- speicherbauform
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Speicher selbst sind verschiedene Bauformen denkbar, die sich vor allem durch das gewählte Baumaterial (Beton, Kunststoffdichtung etc.) und die Ausführung (offen, abgedeckt) unterscheiden. Sie unterscheiden sich grundsätzlich nicht von anderen Speichern. Maßgebend ist insbesondere das Platzangebot. | die Art des Bauwerks (z. B. offen oder geschlossen, Betonbecken oder Erdbecken), | Das aufbereitete Wasser wird in einem Teich zwischengespeichert. — printed p.56 / p.58 / p.79', verification_note='md-verified 2026-09-05 (§7.3 + §8.3 + D.1, printed p.56 / p.58 / p.79 derived) [VC] — CAVEAT: the md prints the two axes (Beton/Kunststoffdichtung × offen/abgedeckt) and "Erdbecken"/"Teich" separately; the four combined enum values are EKOWAI''s granularity', verified_at=now() where id='81d37c77-61a9-4bca-937a-a965e996f180' and verification_status not in ('verified_against_standard','corrected');
-- sekundaerdesinfektion_verfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Daher sollte die Desinfektion mit chlorhaltigen Mitteln und Chlordioxid, ähnlich dem Ansatz bei der Trinkwasserversorgung, einzig als Restdesinfektion und zur Verhinderung von Wiederverkeimung bei längeren Transport- und Speicherdauern eingesetzt werden. Dabei ist Chlordioxid das Desinfektionsmittel der Wahl. | Unter bestimmten Umständen kann es sinnvoll bzw. erforderlich sein, eine Sekundärdesinfektion in das weitere Transport- bzw. Verteilungsnetz zu integrieren. | Peressigsäure, Perameisensäure und Wasserstoffperoxid besitzen wegen der hohen Reaktivität ( $\mathrm{H}_{2} \mathrm{O}_{2}$ ) bzw. Instabilität (Persäuren) keine Depotwirkung (Haaken 2015). — printed p.43 / p.40 / p.45', verification_note='md-verified 2026-09-05 (§5.4.3 Chlor und Chlordioxid + §5.4.2 + §5.4.3 Wasserstoffperoxid, printed p.43 / p.40 / p.45 derived) [VC] — free text for a printed choice (ClO2 "Desinfektionsmittel der Wahl"; Persäuren/H2O2 ohne Depotwirkung) → selection widget candidate; add §5.4.3 to clause (STAGED S-1 / S-10)', verified_at=now() where id='29ddd819-bfed-4043-8460-807caf187e78' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-15 · Kosten- und Umweltbilanz & Genehmigung ########################
-- kostenkennwert_aufbereitung
update public.fields set verification_status='verified_against_standard', verification_quote='Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E : | Mechanisch-biologische Abwasserbehandlung: & $0,7 € / \mathrm{m}^{3}$ bis 1,6 | Ozonung zum Spurenstoffrückhalt (nachgeschaltet): & zusätzlich $0,08 € / \mathrm{m}^{3}$ bis $0,22 € / \mathrm{m}^{3} \mathrm{SW}$, | Aktivkohleadsorption zum Spurenstoffrückhalt: & zusätzlich $0,08 € / \mathrm{m}^{3}$ bis $0,35 € / \mathrm{m}^{3} \mathrm{SW}$. | Membranbelebungsverfahren: $0,85 € / \mathrm{m}^{3}$ bis $1,7 € / \mathrm{m}^{3} \mathrm{SW}$. — printed p.57–58', verification_note='md-verified 2026-09-05 (§8.2 Kosten für die Wasseraufbereitung, printed p.57–58 derived) [VC] — "grobe Richtwerte" per stage, Bezugsjahr 2020; the field is one number for a printed per-stage list (STAGED S-10); the md prints the Mech.-biol. upper bound as "1,6" without unit (OCR)', verified_at=now() where id='deed98af-3806-4a61-ae5b-e9a8954ac2ed' and verification_status not in ('verified_against_standard','corrected');
-- baupreisindex_bezugsjahr
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend genannten Werte können im Zuge einer Anfangsbetrachtung einen ersten Einblick geben. Da es sich um Erfahrungswerte handelt, ist das Bezugsjahr von wesentlicher Bedeutung. Eine Umrechnung auf das aktuelle Betrachtungsjahr mithilfe von Baupreisindizes ist somit immer erforderlich. | Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. — printed p.57', verification_note='md-verified 2026-09-05 (§8.1 + §8.2, printed p.57 derived) [VC] — printed Bezugsjahr of the Richtwerte = 2020; "immer erforderlich" supports REQ-14 (warn)', verified_at=now() where id='0e90661c-0af6-4a11-bef6-c50ce85b8b46' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12002-25 · Wartung & Reinigung der Aufbereitungsstufen ########################
-- arbeitsschutz_unterweisung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Hinweise dieses Merkblatts dienen zur Abwendung einer von der Wasserwiederverwendung ausgehenden Gefährdung. Die allgemeinen Regeln zum Umgang mit Gefahrstoffen sind aus allgemeinen Vorsorgegründen zu beachten. Insbesondere die Regeln zur persönlichen Hygiene sind strikt zu beachten. Jeder Beschäftigte, der mit aufbereitetem Wasser in Kontakt kommt, ist unter anderem in Form eines Gefahrenhinweisblatts in Bezug auf die zu beachtenden Gefahren zu informieren. | Die Integration weitergehender Aufbereitungstechnologien in bestehende Anlagen zur Abwasserbehandlung oder in separaten Aufbereitungseinrichtungen ist in den Arbeits- und Gesundheitsschutzplänen entsprechend zu berücksichtigen. — printed p.53', verification_note='md-verified 2026-09-05 (§6.6 Gesundheitsschutz und Arbeitssicherheit, printed p.53 derived) [VC] — "ist … zu informieren": hard; no gate (STAGED S-5 note)', verified_at=now() where id='a66370c5-2688-4273-9856-8fc883818156' and verification_status not in ('verified_against_standard','corrected');
-- schulungsnachweis
update public.fields set verification_status='verified_against_standard', verification_quote='Das Betriebspersonal von Anlagen zur weitergehenden Behandlung und Aufbereitung von kommunalem Abwasser mit dem Ziel einer Wasserwiederverwendung muss die Bereitstellung einer adäquaten Wasserqualität gewährleisten. Diese Qualitätssicherung setzt ein umfassendes Verständnis des Risikomanagements und damit aller Faktoren voraus, die die Wasserqualität unter Umständen nachteilig beeinflussen können. | Der Betreiber der Aufbereitungseinrichtung hat die entsprechende Unterweisung und regelmäßige Schulung des Personals sowie die Bereitstellung entsprechender Handlungsanweisungen insbesondere für Störfälle (siehe 6.3) sicherzustellen. — printed p.54', verification_note='md-verified 2026-09-05 (§6.7 Schulungsbedarf für Betriebspersonal, printed p.54 derived) [VC] — "hat … sicherzustellen": hard; no gate (STAGED S-5 note)', verified_at=now() where id='ce41428b-0fd9-441f-8f67-118471a5536e' and verification_status not in ('verified_against_standard','corrected');


-- ============================================================================
-- Section B · EQUATIONS (4 rows; prior status needs_engineer_review on all four)
-- ============================================================================
-- Gl. 1  log10_reduktion = log10(c_zulauf / c_ablauf)  (ws 05)
update public.equations set verification_status='verified_against_standard', verification_quote='Die $\log _{10}$-Reduktion wird jeweils aus der Zulaufkonzentration $C_{\text {zulauf }}$ und Ablaufkonzentration $C_{\text {Ablauf }}$ der Indikatororganismen berechnet: | $\log _{10} \text {-Reduktion }=\log _{10}\left(C_{\text {Zulauf }} / C_{\text {Ablauf }}\right) \tag{1}$ | Hierbei müssen mindestens $90 \%$ der Proben die Leistungsziele erreichen (Klasse A). | Für den Fall, dass die Konzentration im Ablauf $C_{\text {Ablauf }}$ unterhalb der Nachweisgrenze ist, ist die $\log _{10}$ Reduktion mit der Nachweisgrenze zu ermitteln. — printed p.19 / p.75', verification_note='md-verified 2026-09-05 (§3.3.2 Gl. (1) + Anhang C.2, printed p.19 / p.75 derived) [VC] — formula matches the print; the "<NWG → use NWG" branch is printed but not encoded (STAGED S-10)', verified_at=now() where id='0ad3e66f-58bc-4869-9dc6-f5e888345f06' and verification_status <> 'verified_against_standard';
-- Gl. C.2-1  perzentil_10_log10 = mw_log10 - 1.282 * sd_log10  (ws 05)
update public.equations set verification_status='verified_against_standard', verification_quote='Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. Die Ermittlung ist beispielhaft in Bild C. 1 dargestellt. | 10. Perzentil $=\mathrm{MW}-1,282 \cdot \mathrm{SD}$ (als Schätzwert der Wahrscheinlichkeitsverteilung; Klasse A) | Mittelwert & MW & 6,58 | Standardabweichung & SD & 0,30 | k-Faktor & k & 1,282 | 10. Perzentil & & 6,20 | Leistungsziel & & 6,00 | 10. Perzentil $=\mathrm{MW}-\mathrm{k} \cdot \mathrm{SD}$ — printed p.75', verification_note='md-verified 2026-09-05 (Anhang C.2 + Bild C.1 worked example, printed p.75 derived) [VC] — worked example re-computed: 6,58 − 1,282 × 0,30 = 6,195 ≈ 6,20 ✓; the constant is hard-coded in the formula while k_faktor_normal exists as a separate hand-enterable field (STAGED S-10)', verified_at=now() where id='e872edf5-09d1-4d27-9238-08a6dc519392' and verification_status <> 'verified_against_standard';
-- Gl. C.2-2  perzentil_50_log10 = median(log10_reduktionen)  (ws 05)
update public.equations set verification_status='verified_against_standard', verification_quote='Aus der Gesamtheit der ermittelten $\log _{10}$-Reduktionswerte kann das geforderte Perzentil analytisch berechnet werden, wobei der Median, der Mittelwert (MW) und die Standardabweichung der Stichprobe (SD) verwendet werden. | 50. Perzentil = Median (Klassen B-1 und C-1) | Klassen B-1 und C-1: Das 50. Perzentil (Median) der Verteilung der $\log _{10}$-Reduktionen muss das Leistungsziel erreichen oder übersteigen. — printed p.75 / p.74', verification_note='md-verified 2026-09-05 (Anhang C.2 + C.1, printed p.75 / p.74 derived) [VC] — formula matches the print (median over the paired LRV set)', verified_at=now() where id='0f237c28-2fc3-451a-b557-9dfe44231ef2' and verification_status <> 'verified_against_standard';
-- Gl. C.2-3  lrv_i = log10(x_i / y_i)  (ws 05)
update public.equations set verification_status='verified_against_standard', verification_quote='Wenn sich die Aufbereitungseinrichtung innerhalb der spezifizierten Betriebsbedingungen befindet, werden aus den Zu- und Ablaufwerten paarweise die $\log _{10}$-Reduktionen berechnet: | $\log _{10}$-Reduktion $=\log _{10}$ ( $C_{\text {Zulauf }} / C_{\text {Ablauf }}$ ) | Anzahl & Zulauf & Ablauf | $\mathbf{1}$ & $\mathrm{x}_{1}=\mathbf{8 , 4} \cdot \mathbf{1 0} 0^{5}$ & $\mathrm{y}_{1}=0,3$ | $\operatorname{LRV}_{1}=6,45$ | $\operatorname{LRV}_{\mathrm{i}}=\log _{10}\left(\mathrm{x}_{\mathrm{i}} / \mathrm{y}_{\mathrm{i}}\right)$ — printed p.75', verification_note='md-verified 2026-09-05 (Anhang C.2 + Bild C.1, printed p.75 derived) [VC] — worked example re-computed: log10(8,4·10^5 / 0,3) = 6,447 ≈ 6,45 ✓; y_3 "< 0,05" → LRV_3 "> 7,16" shows the printed NWG branch (not encoded, STAGED S-10)', verified_at=now() where id='93bc49a5-c3f8-4aa1-9226-85bc436ec4ef' and verification_status <> 'verified_against_standard';
